void swap(std::basic_spanbuf<CharT, Traits> &lhs,

    std::basic_spanbuf<CharT, Traits> &rhs);

examples.code:
#include <spanstream>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    char storage[16] = "42";
    std::spanbuf buffer{std::span<char>{storage}, std::ios::in | std::ios::out};
    buffer.span(std::span<char>{storage});
    assert(buffer.pubseekoff(0, std::ios::beg, std::ios::in) == 0);
    assert(buffer.pubseekoff(0, std::ios::beg, std::ios::in) == 0);
    assert(buffer.sbumpc() == '4');
    assert(buffer.pubseekpos(1, std::ios::in) == 1);
    buffer.pubsetbuf(storage, 16);
    char backup[16]{};
    std::spanbuf other{std::span<char>{backup}};
    other = std::move(buffer);
    other.swap(buffer);
    std::swap(other, buffer);
}
